{"content": "#!/usr/bin/env python3
"""
Rebuild Tomorrow Is Still Open HTML with:
- Clean single TOC
- Proper heading tags (h2 for parts, h2 for chapters)
- 5 B&W pencil sketch images as part dividers
- 5 historical context passages with border styling
- PDF generation
"""

import re
import base64
import os
from pathlib import Path
from bs4 import BeautifulSoup

# Paths
BASE_DIR = Path("/home/bob/books/The_Unwritten_Future/output")
MD_PATH = BASE_DIR / "Tomorrow_is_Still_Open_REVISED.md"
HTML_PATH = BASE_DIR / "Tomorrow_is_Still_Open_REVISED.html"
IMG_DIR = Path("/home/bob/books/The_Unwritten_Future/output/part_images")
OUT_HTML = BASE_DIR / "Tomorrow_is_Still_Open_FINAL.html"
OUT_PDF = BASE_DIR / "Tomorrow_is_Still_Open_FINAL.pdf"

# Load context passages
import json
with open(IMG_DIR / "context_passages.json") as f:
    context_data = json.load(f)

# Part definitions
PARTS = [
    {"num": "One", "title": "The Ignition", "img": "part1_ignition.png", "ctx_key": "part1"},
    {"num": "Two", "title": "The Building", "img": "part2_building.png", "ctx_key": "part2"},
    {"num": "Three", "title": "The Particle and The Person", "img": "part3_particle.png", "ctx_key": "part3"},
    {"num": "Four", "title": "Building Forward", "img": "part4_forward.png", "ctx_key": "part4"},
    {"num": "Five", "title": "The Futures Beyond", "img": "part5_future.png", "ctx_key": "part5"},
]

CHAPTERS = [
    {"num": "One", "title": "The Shock"},
    {"num": "Two", "title": "The Echoes of Sputnik and a Family Legacy"},
    {"num": "Three", "title": "Mr. Chips"},
    {"num": "Four", "title": "The Garage"},
    {"num": "Five", "title": "The Spark Ignites"},
    {"num": "Six", "title": "Life as an Engineer"},
    {"num": "Seven", "title": "Foundations"},
    {"num": "Eight", "title": "The Diagnosis"},
    {"num": "Nine", "title": "The New Partnership"},
    {"num": "Ten", "title": "Building a New Life"},
    {"num": "Eleven", "title": "What Remains Unwritten"},
    {"num": "Twelve", "title": "The Threshold"},
    {"num": "Thirteen", "title": "Echoes of Tomorrow"},
    {"num": "Fourteen", "title": "The Human Horizon"},
    {"num": "Fifteen", "title": "The World Remade"},
    {"num": "Sixteen", "title": "Inheritance"},
]

# Map: chapter title patterns for parsing markdown
CHAPTER_PATTERNS = []
for ch in CHAPTERS:
    CHAPTER_PATTERNS.append(f"Chapter {ch['num']}: {ch['title']}")

PART_PATTERNS = []
for p in PARTS:
    PART_PATTERNS.append(f"Part {p['num']}: {p['title']}")


def parse_markdown_sections(md_text):
    """Parse markdown into sections: [('book_title', content), ('part_title', content), ('chapter_title', content), ('text', content), ...]"""
    lines = md_text.split('\n')

    sections = []
    current_type = 'text'
    current_content = []

    i = 0
    while i < len(lines):
        line = lines[i]
        stripped = line.strip()

        # Check for book title / header
        if stripped == "Tomorrow Is Still Open":
            if current_content:
                sections.append((current_type, '\n'.join(current_content)))
            current_type = 'book_title'
            current_content = [stripped]
            i += 1
            continue

        # Check for "A Memoir by Bob J Mills"
        if stripped == "A Memoir by Bob J Mills":
            if current_content:
                sections.append((current_type, '\n'.join(current_content)))
            current_type = 'subtitle'
            current_content = [stripped]
            i += 1
            continue

        # Check for part titles
        part_match = False
        for p in PARTS:
            if stripped == f"Part {p['num']}: {p['title']}":
                if current_content:
                    sections.append((current_type, '\n'.join(current_content)))
                current_type = 'part'
                current_content = [stripped]
                p['index'] = len(sections)  # Track where this part appears
                part_match = True
                break
        if part_match:
            i += 1
            continue

        # Check for chapter titles
        ch_match = False
        for c in CHAPTERS:
            pattern = f"Chapter {c['num']}: {c['title']}"
            if stripped == pattern:
                if current_content:
                    sections.append((current_type, '\n'.join(current_content)))
                current_type = 'chapter'
                current_content = [stripped]
                ch_match = True
                break
        if ch_match:
            i += 1
            continue

        # Check for chapter variations (e.g. "Chapter One: The Shock")
        ch_variation = False
        for c in CHAPTERS:
            pattern = f"Chapter {c['num']}: {c['title']}"
            if stripped == pattern:
                if current_content:
                    sections.append((current_type, '\n'.join(current_content)))
                current_type = 'chapter'
                current_content = [stripped]
                ch_variation = True
                break
        if ch_variation:
            i += 1
            continue

        # Regular content
        current_content.append(line)
        i += 1

    if current_content:
        sections.append((current_type, '\n'.join(current_content)))

    return sections


def clean_markdown_artifacts(text):
    """Clean markdown artifacts that shouldn't be in the content."""
    # Remove duplicate transition lines
    lines = text.split('\n')
    cleaned = []
    seen_transitions = set()
    for line in lines:
        stripped = line.strip()
        if stripped.startswith('Transition:'):
            if stripped in seen_transitions:
                continue
            seen_transitions.add(stripped)
        cleaned.append(line)
    return '\n'.join(cleaned)


def markdown_to_html_simple(text):
    """Simple markdown to HTML converter for our specific format."""
    html = text

    # H3 subheadings (### ...)
    html = re.sub(r'^###\s+(.+)$', r'<h3>\1</h3>', html, flags=re.MULTILINE)

    # Italic (*...*)
    html = re.sub(r'\*([^*]+)\*', r'<em>\1</em>', html)

    # HR (---)
    html = re.sub(r'\n---\n', '\n<hr>\n', html)

    # Block quotes (lines starting with >)
    # We handle this inline
    html = re.sub(r'^>\s+(.+)$', r'<blockquote>\1</blockquote>', html, flags=re.MULTILINE)

    # Regular paragraphs - wrap everything that isn't a block element
    lines = html.split('\n')
    result = []
    in_block = False
    block_types = ['<h3>', '<hr>', '<blockquote>', '<div', '</div>']

    for line in lines:
        stripped = line.strip()
        if not stripped:
            result.append('')
            continue

        is_block = any(stripped.startswith(t) for t in block_types)

        if is_block:
            result.append(stripped)
        else:
            result.append(f'<p>{stripped}</p>')

    return '\n'.join(result)


def build_toc():
    """Build the table of contents HTML."""
    toc = '<div class="toc">\n<h2>Table of Contents</h2>\n'

    ch_idx = 0
    for p_idx, part in enumerate(PARTS):
        toc += f'<p class="part">Part {part["num"]}: {part["title"]}</p>\n'
        # Chapters in this part
        part_chapters = []
        if p_idx == 0:  # Part One: Ch 1-3
            part_chapters = CHAPTERS[0:3]
        elif p_idx == 1:  # Part Two: Ch 4-5
            part_chapters = CHAPTERS[3:5]
        elif p_idx == 2:  # Part Three: Ch 6-7
            part_chapters = CHAPTERS[5:7]
        elif p_idx == 3:  # Part Four: Ch 8-12
            part_chapters = CHAPTERS[7:12]
        elif p_idx == 4:  # Part Five: Ch 13-16
            part_chapters = CHAPTERS[12:16]

        for ch in part_chapters:
            toc += f'<p class="chapter">Chapter {ch["num"]}: {ch["title"]}</p>\n'

    toc += '</div>\n'
    return toc


def build_part_divider_page(part_num, part_title, img_path, context_html):
    """Build a part divider page with image and context box."""
    html = f'<div class="part-divider">\n'
    html += f'<h1 class="part-title">Part {part_num}: {part_title}</h1>\n'

    # Insert image if it exists
    if os.path.exists(img_path):
